// Après votre décision : prépare une programmation Blotato par compte réglé.
// Le formulaire de validation renvoie le champ « Décision » : « Programmer » ou « Rejeter ».
const decision = String(($input.first().json || {})["Décision"] || "").toLowerCase();
if (decision !== "programmer") return [];
const d = $("Lire la réponse").first().json.draft;
const s = $("Réglages").first().json.settings;
const texts = { fr: d.post_fr, ary_latin: d.post_ary_latin, ary_arabe: d.post_ary_arabe };
const VIDEO = ["tiktok", "instagram", "youtube", "pinterest"];
const out = [];
for (const t of s.blotato || []) {
  const text = texts[t.langue];
  if (!t.accountId || !t.platform || !text || VIDEO.includes(t.platform)) continue;
  const target = { targetType: t.platform };
  if (t.pageId) target.pageId = String(t.pageId);
  out.push({
    json: {
      target_label: `${t.platform} (${t.langue})`,
      blotato_request: {
        post: { accountId: String(t.accountId), content: { text, mediaUrls: [], platform: t.platform }, target },
        useNextFreeSlot: true,
      },
    },
  });
}
return out;

// Après votre décision : si aucun compte Blotato n'est utilisable, vous publiez vous-même.
// Le formulaire de validation renvoie le champ « Décision » : « Programmer » ou « Rejeter ».
const decision = String(($input.first().json || {})["Décision"] || "").toLowerCase();
const s = $("Réglages").first().json.settings;
const d = $("Lire la réponse").first().json.draft;
const VIDEO = ["tiktok", "instagram", "youtube", "pinterest"];
const usable = (s.blotato || []).filter((t) => t.accountId && t.platform && !VIDEO.includes(t.platform));
if (decision === "rejeter") return [{ json: { text: "Brouillon rejeté. Rien n'est publié." } }];
if (decision !== "programmer") return [];
if (usable.length && d.format !== "video_courte") return [];
const why = d.format === "video_courte" ? "c'est une vidéo à filmer" : "aucun compte Blotato n'est réglé";
return [{ json: { text: `Brouillon validé. À publier vous-même (${why}) : reprenez le texte du message précédent.` } }];

// Alerte si une source du radar répond mal (pilote de 14 jours).
const item = $input.first().json;
if (!item.settings.alerte_sante || !item.body || !Array.isArray(item.body.health)) return [];
const bad = item.body.health.filter((r) => r.days_observed >= 3 && r.day_rate < 0.9);
if (!bad.length) return [];
const lines = bad.map((r) => `• ${r.source} : ${Math.round(r.day_rate * 100)} % de jours bons sur ${r.days_observed}`
  + (r.last_error ? ` (dernière erreur : ${String(r.last_error).slice(0, 120)})` : ""));
return [{ json: { text: "Radar : sources à surveiller\n" + lines.join("\n") } }];
